/**
 * The Wrong Feast Day — structural test generated by compile:encounter (THR-1246).
 * Expected values are baked from the content package, so this file asserts the
 * encounter's actual shape rather than any template's.
 */

import { describe, expect, it } from 'vitest';
import { EASTER_RECKONING_TEMPLATE } from '../easter-reckoning';
import { expandSettings } from '../../settingClasses';
import { drawConsequenceHand, handAfterSwap } from '../../content-eval/consequenceDraw';

describe("The Wrong Feast Day — template structure", () => {
  it('carries its identity', () => {
    expect(EASTER_RECKONING_TEMPLATE.id).toBe('encounter.town.easter_reckoning');
    expect(EASTER_RECKONING_TEMPLATE.reach).toBe('star');
    expect(EASTER_RECKONING_TEMPLATE.rarityTier).toBe(2);
    expect(EASTER_RECKONING_TEMPLATE.steps).toHaveLength(2);
  });

  it('step 0 deals the authored hand', () => {
    const step = EASTER_RECKONING_TEMPLATE.steps[0];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['reckoning.deepen_the_dark', 'reckoning.clear_the_dawn']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['darkness', 'force']);
  });

  it('step 1 deals the authored hand', () => {
    const step = EASTER_RECKONING_TEMPLATE.steps[1];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['reckoning.crack_the_binding', 'reckoning.rouse_the_elder']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['entropy', 'life']);
  });
  it('derives its location subtypes from the declared envelope', () => {
    expect(EASTER_RECKONING_TEMPLATE.settings).toEqual(['urban']);
    expect(EASTER_RECKONING_TEMPLATE.locationSubtypes).toEqual(expandSettings(['urban']));
  });

  it('records exactly the hand its id draws (binding, THR-1145)', () => {
    expect(EASTER_RECKONING_TEMPLATE.consequenceDraw).toEqual(['drive', 'omen']);
    expect(EASTER_RECKONING_TEMPLATE.consequenceDraw).toEqual(
      handAfterSwap(
        drawConsequenceHand({
          templateId: 'encounter.town.easter_reckoning',
          reach: 'star',
          rarityTier: 2,
        }),
        EASTER_RECKONING_TEMPLATE.consequenceSwap,
      ),
    );
  });
});
